import {SCRIPT_FAILURES} from './script-feedback.js';
export {SCRIPT_FAILURES};
// Generated by the execution host, never taken from model arguments or page content.
export const normalizeTraceId = value => typeof value === 'string' && /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i.test(value) ? value : null;
export function progressNote(content) {
  return typeof content === 'string' ? content.trim().replace(/Bearer\s+[^\s"']+/gi, 'Bearer [redacted]').replace(/eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/g, '[redacted]').slice(0, 600) : '';
}
export const TOOL_LABELS = Object.freeze({search_documents: '문서 검색', read_document: '문서 읽기', find_skills: '업무 스킬 찾기', read_skill: '업무 절차 읽기', wiki_query: 'OpenWiki 근거 찾기', recover_tool: '도구 호출 수정', analysis_page: '화면 분석', analysis_research: '문서 조사', analysis_review: '독립 검토', analysis_recovery: '실패 원인 확인', delegate_analysis: '역할별 분석', collect_analysis: '분석 결과 확인', read_analysis_evidence: '분석 근거 확인', cancel_analysis: '분석 중지', image_model: '이미지 모델 전환', recover_model: '모델 연결 복구', wiki_search: 'Wiki 검색', wiki_read: 'Wiki 읽기', source_search: '소스 검색', read_source: '소스 읽기', request_approval: '최종 반영 승인', apply_approved_action: '최종 반영', ask_user: '선택 확인', inspect_images: '이미지 비교', review_task: '요청사항 확인', select_tools: '도구 선택', verify_page: '결과 검증', update_plan: '작업 계획', read_page: '페이지 읽기', inspect_dom: '구조 확인', list_page_storage: '저장 항목 확인', read_page_storage: '저장 정보 읽기', fill_form: '페이지 입력', verify_form: '입력 결과 확인', run_playwright: '브라우저 코드 실행', capture_page: '화면 보기', find_images: '이미지 찾기', attach_images: '이미지 가져오기', click_at: '화면 클릭', browser_snapshot: '화면 확인', drag_element: '드래그', click_element: '클릭', hover_element: '메뉴 확인', press_key: '키 입력', select_option: '항목 선택', scroll_page: '스크롤', navigate_page: '페이지 이동', list_tabs: '탭 찾기', switch_tab: '탭 전환', go_back: '이전 페이지', wait_page: '화면 대기'});

export function normalizeTrace(steps) {
  return (Array.isArray(steps) ? steps : []).flatMap(step => {
    const identity = normalizeTraceId(step?.id) ? {id: step.id} : {};
    if (step?.tool === 'progress_note' && progressNote(step.content)) return [{...identity, tool: 'progress_note', status: 'done', content: progressNote(step.content)}];
    return Object.hasOwn(TOOL_LABELS, step?.tool) && ['running', 'done', 'error', 'cancelled', 'waiting', 'deferred'].includes(step.status) ? [{...identity, tool: step.tool, status: step.status, ...(progressNote(step.label) ? {label: progressNote(step.label).slice(0, 100)} : {}), ...(typeof step.planStep === 'string' && step.planStep.length <= 200 ? {planStep: step.planStep} : {}), ...(step.status === 'error' && Object.hasOwn(SCRIPT_FAILURES, step.reason) ? {reason: step.reason} : {})}] : [];
  }).slice(-32);
}

export function displayTrace(steps, completed = false) {
  const trace = normalizeTrace(steps);
  const reviewed = completed ? trace.findLastIndex(step => step.tool === 'review_task' && step.status === 'done') : -1;
  return trace.map((step, index) => reviewed > index && step.status === 'error' ? {...step, status: 'recovered'} : step);
}
